class Cache
  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  def write(key, payload, stale: false)
    # If a packer is provided, dump the payload to a serialized string
    serialized_payload = if @packer
                           @packer.dump(payload)
                         else
                           payload
                         end

    # Store the serialized payload along with the stale flag
    @store[key] = {
      payload: serialized_payload,
      stale: stale
    }
  end

  def read(key)
    entry = @store[key]
    return nil unless entry

    # If a packer is provided, load the payload from the serialized string
    payload = if @packer
                @packer.load(entry[:payload])
              else
                entry[:payload]
              end

    payload
  end

  def sweep
    # Remove entries marked as stale
    @store.delete_if { |_key, entry| entry[:stale] }
  end
end
