      @meters == other.meters
    else
      @meters == other
    end
  end

  def -(other)
    result = case other
             when Distance
               @meters - other.meters
             when Integer, Float
               @meters - other
             else
               raise TypeError, "Cannot subtract #{other.class} from Distance"
             end
    Distance.new(result)
  end

  def +(other)
    value = case other
            when Distance
              @meters + other.meters
            when Integer, Float
              @meters + other
            else
              raise TypeError, "Cannot add #{other.class} to Distance"
            end
    Distance.new(value)
  end

