class OpenRecord
  def initialize(**attrs)
    attrs.each do |key, value|
      attr_name = key.to_s
      define_method(attr_name) { instance_variable_get("@#{attr_name}") }
      define_method("#{attr_name}=") { |val| instance_variable_set("@#{attr_name}", val) }
      instance_variable_set("@#{attr_name}", value)
    end
  end

  def method_missing(method_name, *args)
    attr_name = method_name.to_s

    # Handle assignment-style calls (e.g., age=)
    if attr_name.end_with?('=')
      key = attr_name.chomp('=').to_sym
      define_method(key) { instance_variable_get("@#{key}") }
      define_method(method_name) { |val| instance_variable_set("@#{key}", val) }
      instance_variable_set("@#{key}", args.first)
      return
    end

    # Handle getter-style calls (e.g., age)
    if instance_variable_defined?("@#{attr_name}")
      return instance_variable_get("@#{attr_name}")
    end

    super
  end

  def respond_to_missing?(method_name, include_private = false)
    attr_name = method_name.to_s

    # Check if assignment method is defined
    return true if attr_name.end_with?('=') && instance_variable_defined?("@#{attr_name.chomp('=')}")

    # Check if getter method is defined (attribute was set)
    return true if instance_variable_defined?("@#{attr_name}")

    super
  end
end
