class OpenRecord
  def initialize(**attrs)
    @attributes = {}
    attrs.each do |key, value|
      name = key.to_s
      define_attribute_methods(name)
      @attributes[name] = value
    end
  end

  def method_missing(method_name, *args)
    method_str = method_name.to_s

    if method_str.end_with?('=')
      attr_name = method_str.chomp('=')
      define_attribute_methods(attr_name) unless @attributes.key?(attr_name)
      @attributes[attr_name] = args.first
      return args.first
    end

    if @attributes.key?(method_str)
      return @attributes[method_str]
    end

    super
  end

  def respond_to_missing?(method_name, include_private = false)
    method_str = method_name.to_s
    if method_str.end_with?('=')
      return true
    end
    @attributes.key?(method_str) || super
  end

  private

  def define_attribute_methods(name)
    return if @attributes.key?(name) && method_defined?(name.to_sym)

    # Define getter
    if !method_defined?(name.to_sym)
      define_singleton_method(name.to_sym) do
        if @attributes.key?(name)
          @attributes[name]
        else
          super
        end
      end
    end

    # Define setter
    setter_name = "#{name}=".to_sym
    unless method_defined?(setter_name)
      define_singleton_method(setter_name) do |value|
        @attributes[name] = value
        value
      end
    end
  end
end
