class Proxy
  def initialize(target)
    @target = target
  end

  def method_missing(method_name, *args, **kwargs, &block)
    if @target.respond_to?(method_name)
      @target.send(method_name, *args, **kwargs, &block)
    else
      super
    end
  end

  def respond_to_missing?(method_name, include_private = false)
    @target.respond_to?(method_name, include_private) || super
  end

  def method(method_name)
    if @target.respond_to?(method_name)
      # Create a proxy-bound method that forwards to the target
      target_method = @target.method(method_name)
      ProxyBoundMethod.new(target_method, self)
    else
      raise NameError, "undefined method `#{method_name}' for #<#{self.class}:#{self.object_id}>"
    end
  end

  class ProxyBoundMethod
    def initialize(original_method, proxy)
      @original_method = original_method
      @proxy = proxy
    end

    def call(*args, **kwargs, &block)
      @original_method.call(*args, **kwargs, &block)
    end
  end
end

# Override Module#method for the target context when called via proxy
class Module
  alias_method :ruby_original_method, :method
end
